/**
 * Model Resolver for Eliza API
 *
 * Resolves model names to their correct vendor and endpoint configuration.
 * Supports anthropic, openai, openrouter, and internal (Yandex) vendors.
 */
import createLogger from "@yandex-int/yandex-logger";
import { ElizaApiError, ElizaNetworkError, ElizaTimeoutError, } from "./client.js";
const logger = createLogger({ name: "model-resolver" });
/** Shared endpoint used by all OpenRouter models */
const OPENROUTER_ENDPOINT = "/openrouter/v1/chat/completions";
// ============================================================================
// Error Classes
// ============================================================================
export class ModelNotFoundError extends Error {
    modelId;
    availableModels;
    constructor(modelId, availableModels) {
        super(`Model '${modelId}' not found in Eliza API`);
        this.modelId = modelId;
        this.availableModels = availableModels;
        this.name = "ModelNotFoundError";
    }
}
export class UnsupportedVendorError extends Error {
    modelId;
    vendor;
    constructor(modelId, vendor) {
        super(`Model '${modelId}' has unsupported vendor '${vendor}'. Supported vendors: anthropic, openai, openrouter, internal`);
        this.modelId = modelId;
        this.vendor = vendor;
        this.name = "UnsupportedVendorError";
    }
}
export class ModelResolver {
    baseUrl;
    timeout;
    token;
    /** Cached models list */
    modelsCache = null;
    constructor(config) {
        this.baseUrl = config.baseUrl ?? "https://api.eliza.yandex.net";
        this.timeout = config.timeout ?? 10000;
        this.token = config.token;
    }
    /**
     * Fetch all models from the Eliza API.
     * Results are cached after first call.
     */
    async getModels() {
        if (this.modelsCache) {
            return this.modelsCache;
        }
        logger.info("Fetching models from Eliza API...");
        const response = await this.request("/v1/models");
        this.modelsCache = response.data;
        logger.info(`Fetched ${this.modelsCache.length} models from Eliza API`);
        return this.modelsCache;
    }
    /**
     * Clear the models cache to force a fresh fetch.
     */
    clearCache() {
        this.modelsCache = null;
    }
    /**
     * Find a model by ID.
     * Searches by exact ID match first, then by versions/aliases.
     */
    async findModel(modelId) {
        const models = await this.getModels();
        // First try exact ID match
        let model = models.find((m) => m.id === modelId);
        if (model) {
            return model;
        }
        // Then try versions match
        model = models.find((m) => m.versions?.includes(modelId));
        if (model) {
            return model;
        }
        // Then try aliases match
        model = models.find((m) => m.aliases?.includes(modelId));
        if (model) {
            return model;
        }
        return null;
    }
    /**
     * Resolve a model ID to its vendor and endpoint configuration.
     *
     * @param modelId - The model ID to resolve (e.g., "claude-opus-4-5", "openai/gpt-5.2", "zeliboba_lts_235b_aligned_quantized_202510")
     * @returns Resolved model configuration with vendor, endpoint, and base URL
     * @throws UnsupportedVendorError if vendor is not supported
     */
    async resolve(modelId) {
        const model = await this.findModel(modelId);
        if (!model) {
            logger.info(`Model '${modelId}' not found in Eliza catalog, falling back to openrouter vendor`);
            const endpoint = OPENROUTER_ENDPOINT;
            const baseUrl = this.getBaseUrl("openrouter");
            return {
                modelId,
                vendor: "openrouter",
                endpoint,
                baseUrl,
                raw: {
                    id: modelId,
                    vendor: "openrouter",
                    endpoint,
                },
            };
        }
        if (!this.isSupportedVendor(model.vendor)) {
            throw new UnsupportedVendorError(modelId, model.vendor);
        }
        const vendor = model.vendor;
        const endpoint = this.normalizeEndpoint(model.endpoint, vendor);
        const baseUrl = this.getBaseUrl(vendor);
        logger.info(`Resolved model '${modelId}': vendor=${vendor}, endpoint=${endpoint}, baseUrl=${baseUrl}`);
        return {
            modelId,
            vendor,
            endpoint,
            baseUrl,
            raw: model,
        };
    }
    /**
     * Get all models for a specific vendor.
     */
    async getModelsByVendor(vendor) {
        const models = await this.getModels();
        return models.filter((m) => m.vendor === vendor);
    }
    /**
     * Search models by partial ID match.
     */
    async searchModels(query) {
        const models = await this.getModels();
        const lowerQuery = query.toLowerCase();
        return models.filter((m) => m.id.toLowerCase().includes(lowerQuery) ||
            m.title?.toLowerCase().includes(lowerQuery) ||
            m.versions?.some((v) => v.toLowerCase().includes(lowerQuery)) ||
            m.aliases?.some((a) => a.toLowerCase().includes(lowerQuery)));
    }
    // ========================================================================
    // Private Methods
    // ========================================================================
    /**
     * Check if a vendor is supported.
     */
    isSupportedVendor(vendor) {
        return (vendor === "anthropic" ||
            vendor === "openai" ||
            vendor === "openrouter" ||
            vendor === "internal");
    }
    /**
     * Normalize the endpoint path.
     * For internal vendor with /generative endpoints, append /v1/chat/completions.
     */
    normalizeEndpoint(endpoint, vendor) {
        if (vendor === "internal") {
            // Check if endpoint ends with /generative (without /v1/chat/completions)
            if (endpoint.endsWith("/generative")) {
                return `${endpoint}/v1/chat/completions`;
            }
            // If it already has /v1/chat/completions or other suffix, use as is
            return endpoint;
        }
        // For anthropic, openai, and openrouter, use endpoint as is
        return endpoint;
    }
    /**
     * Get the base URL for a vendor.
     * The endpoint already contains the full path (e.g., /anthropic/v1/messages),
     * so we just need to add /raw prefix.
     */
    getBaseUrl(_vendor) {
        // All vendors use /raw prefix, endpoint contains the vendor-specific path
        return `${this.baseUrl}/raw`;
    }
    /**
     * Make an HTTP GET request to the Eliza API.
     */
    async request(path) {
        const url = `${this.baseUrl}${path}`;
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), this.timeout);
        try {
            const response = await fetch(url, {
                method: "GET",
                headers: {
                    Authorization: `OAuth ${this.token}`,
                },
                signal: controller.signal,
            });
            if (!response.ok) {
                const body = await response.text();
                throw new ElizaApiError(`Eliza API error at ${path}: ${response.status} ${response.statusText}`, response.status, body);
            }
            return (await response.json());
        }
        catch (error) {
            if (error instanceof ElizaApiError) {
                throw error;
            }
            if (error instanceof Error && error.name === "AbortError") {
                throw new ElizaTimeoutError(this.timeout, path);
            }
            throw new ElizaNetworkError(`Network error during GET ${path}: ${error instanceof Error ? error.message : String(error)}`, error instanceof Error ? error : undefined);
        }
        finally {
            clearTimeout(timeoutId);
        }
    }
}
